/* Local HTMX-compatible runtime for this app's hx-post subset. */
(()=>{
  "use strict";
  const resolveTarget=(element,selector)=>{
    if(!selector)return element;
    if(selector.startsWith("closest "))return element.closest(selector.slice(8));
    return document.querySelector(selector);
  };
  const swap=(target,html,mode)=>{
    if(!target)return;
    if(mode==="innerHTML")target.innerHTML=html;
    else target.outerHTML=html;
  };
  async function request(element,url,method){
    const target=resolveTarget(element,element.getAttribute("hx-target"));
    const options={method,headers:{"HX-Request":"true"}};
    if(method!=="GET")options.body=new FormData(element);
    element.dispatchEvent(new CustomEvent("htmx:beforeRequest",{bubbles:true,detail:{elt:element}}));
    try{
      const response=await fetch(url,options);
      if(response.headers.get("HX-Refresh")==="true"){
        window.location.reload();
        return;
      }
      const html=await response.text();
      const detail={xhr:response,shouldSwap:true,isError:!response.ok,target};
      document.body.dispatchEvent(new CustomEvent("htmx:beforeSwap",{detail}));
      if(detail.shouldSwap)swap(target,html,element.getAttribute("hx-swap")||"innerHTML");
      const triggers=response.headers.get("HX-Trigger");
      if(triggers)triggers.split(",").forEach(name=>document.body.dispatchEvent(new CustomEvent(name.trim(),{bubbles:true})));
      document.body.dispatchEvent(new CustomEvent("htmx:afterSwap",{detail:{target}}));
    }catch(error){
      document.body.dispatchEvent(new CustomEvent("htmx:responseError",{detail:{error},bubbles:true}));
    }
  }
  document.addEventListener("submit",event=>{
    const form=event.target.closest("form[hx-post]");
    if(!form)return;
    event.preventDefault();
    if(!form.reportValidity())return;
    request(form,form.getAttribute("hx-post"),"POST");
  });
  window.htmx={
    on:(name,handler)=>document.body.addEventListener(name,handler),
    trigger:(element,name)=>element.dispatchEvent(new CustomEvent(name,{bubbles:true}))
  };
})();
